void __fastcall TEXT_FreeHoverText(D2HoverTextStrc * pHover) {
    D2TextLineStrc** pMemoryToFree = (D2TextLineStrc**)D2Common::Chat::HOVERTEXT_GetTextLineList(pHover);
    if (pMemoryToFree) {
      TEXT_FreeTextLineList(*pMemoryToFree);
      D2_FREE_AT(pMemoryToFree, ".\\UI\\text.cpp", 0x68e);
      D2Common::Chat::HOVERTEXT_SetTextLineList(pHover, nullptr);
    }

    D2Common::Chat::Free(nullptr, pHover);
}

static void __stdcall TEXT_SetUnitHoverText(uint32_t dwUnused, char * szText, uint8_t nLanguageCode, D2UnitStrc * pUnit) {
    char chCur;
    if (!pUnit) {
      return;
    }

    char* pszScan;
    if (strlen(szText) == 0) {
      if (pUnit->pHoverText) {
        D2Common::Chat::Free(nullptr, pUnit->pHoverText);
      }

      pUnit->pHoverText = 0;
      return;
    }

    D2HoverTextStrc* pHover = D2Common::Chat::Alloc(nullptr, szText, gnTextOverheadCounter);
    D2Common::Chat::SetLanguageCode(pHover, nLanguageCode);
    if (pUnit->pHoverText) {
      D2Common::Chat::Free(nullptr, pUnit->pHoverText);
    }

    pUnit->pHoverText = pHover;
}

// Converts and displays game message - handles player names, ignore lists, colored text formatting
void __fastcall TEXT_ProcessChatMessage(MessageStrc * pMessage) {
    uint32_t nCheckResult;
    char* pszName;
    char* pbNameScan;
    int i;
    uint16_t* pszWideOut;
    uint16_t wszMsgBuf[612];
    uint16_t wcWideStart[256];
    uint16_t wszFormatBuf[612];
    uint16_t wszMessage[256];
    uint16_t wszNameBuf2[16];
    uint16_t wszShortName[16];
    char szNameBuf[20];
    char byChar;
    int32_t nMaxName;
    if (!pMessage->entityType) {
      nCheckResult = GAME::Roster::ROSTER_CheckPlayerNotHostile(pMessage->id);
      if (!nCheckResult) {
        return;
      }
    }

    D2UnitStrc* unit = UNIT::Player::UNITS_FindClientSideUnit(pMessage->id, (eD2UnitType)pMessage->entityType);
    memset(szNameBuf, 0, 17 * sizeof(szNameBuf[0]));
    if (unit && unit->eUnitType == UNIT_PLAYER || pMessage->name[0] != '\0') {
      ::IgnoreList* pIgnoreList;
      nMaxName = 0x11;
      if (unit) {
        pszName = D2Common::Units::GetPlayerName(unit);
      } else {
        pszName = pMessage->name;
      }

      Storm::Source::SSTR::SStrCopy(szNameBuf, pszName, nMaxName);
      pIgnoreList = D2Common::Chat::Ignorelist::MISC_GetIgnorelist();
      nMaxName = pIgnoreList->_vfptr->CheckIgnored(pIgnoreList, szNameBuf);
      if (nMaxName) {
        return;
      }

      pIgnoreList = D2Common::Chat::Ignorelist::MISC_GetIgnorelist();
      nMaxName = pIgnoreList->_vfptr->CheckAccountNameIgnored(pIgnoreList, pMessage->message);
      if (nMaxName) {
        return;
      }
    }

    for (i = 0; i < 0x100; i++) {
      wszMessage[i] = L'\0';
    }

    pszName = pMessage->message;
    uint8_t byMsgType = TEXT_ConvertCharToWideWithLanguage(0, pszName, (uint32_t)pMessage->language, (uint16_t*)wszMessage);
    if (!byMsgType) {
      return;
    }

    wszMessage[0xff] = L'\0';
    if (pMessage->messageType == 4) {
      TEXT_PrintGameString(wszMessage, pMessage->messageColor);
      return;
    }

    Fog::File::CONTAINER_InitializeBuffer(wszFormatBuf, 2, 0x264, D2Lang::Unicode::UNISYS::STRING_ZeroOneWCHAR);
    Fog::File::CONTAINER_InitializeBuffer(wszMsgBuf, 2, 0x264, D2Lang::Unicode::UNISYS::STRING_ZeroOneWCHAR);
    Fog::File::CONTAINER_InitializeBuffer(wszShortName, 2, 0x10, D2Lang::Unicode::UNISYS::STRING_ZeroOneWCHAR);
    byMsgType = pMessage->messageType;
    if (byMsgType == 6) {
      D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszMsgBuf, pszName, 0x100);
      D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszShortName, pMessage->name, 0x10);
      D2Lang::Unicode::UNISYS::UNICODE_FormatWideString(0x264, wszFormatBuf, D2Lang::StrTable::strtable::GetLocaleString(0xe4a), wszShortName, wszMsgBuf);
      ui::UI_RemoveColorCodesFromString(wszFormatBuf);
      TEXT_PrintGameString(wszFormatBuf, 2);
      return;
    }
    if (byMsgType == 2) {
      pbNameScan = pMessage->name;
      pbNameScan = pbNameScan + strlen(pbNameScan) + 1;
      pszName = pszName + strlen(pszName) + 1;
      if (pbNameScan + (-1 - (intptr_t)(pMessage->name + 1)) < (char*)0xf) {
        D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszShortName, pMessage->name, 0x10);
        D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszFormatBuf, wszShortName);
        pszWideOut = D2Lang::StrTable::strtable::GetLocaleString(0xe46);
        D2Lang::Unicode::UNISYS::AppendToBuffer(wszFormatBuf, pszWideOut);
        D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszMsgBuf, wszMessage);
        D2Lang::Unicode::UNISYS::AppendToBuffer(wszFormatBuf, wszMsgBuf);
        TEXT_PrintGameString(wszFormatBuf, 2);
        return;
      }
      if ((intptr_t)pszName - (intptr_t)(pMessage->message + 1) <= 0x131) {
        D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszFormatBuf, wszMessage);
        TEXT_PrintGameString(wszFormatBuf, 2);
        return;
      }
    } else {
      switch (byMsgType) {
        case 1:
          {
            if (!pMessage->entityType || pMessage->entityType == 1) {
              TEXT_PrintGameString(wszMessage, pMessage->messageColor);
              return;
            }

            pbNameScan = pMessage->name;
            pbNameScan = pbNameScan + strlen(pbNameScan) + 1;
            pszName = pszName + strlen(pszName) + 1;
            if (pbNameScan + (-1 - (intptr_t)(pMessage->name + 1)) < (char*)0xf) {
              Fog::File::CONTAINER_InitializeBuffer(wszNameBuf2, 2, 0x10, D2Lang::Unicode::UNISYS::STRING_ZeroOneWCHAR);
              D2Lang::Unicode::UNISYS::STRING_CopyCharToWCharWithSetMaxSize(wszNameBuf2, pMessage->name, 0x10);
              D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszFormatBuf, wszNameBuf2);
              ui::AppendAsWideChar(wszFormatBuf, 4);
              pszWideOut = D2Lang::StrTable::strtable::GetLocaleString(0xfd0);
              D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszMsgBuf, pszWideOut);
              D2Lang::Unicode::UNISYS::AppendToBuffer(wszMsgBuf, wszMessage);
              ui::AppendAsWideChar(wszMsgBuf, 0);
              D2Lang::Unicode::UNISYS::AppendToBuffer(wszFormatBuf, wszMsgBuf);
              TEXT_PrintGameString(wszFormatBuf, pMessage->messageColor);
              return;
            }
            if ((intptr_t)pszName - (intptr_t)(pMessage->message + 1) <= 0x131) {
              D2Lang::Unicode::UNISYS::STRING_CopyWideString(wszFormatBuf, wszMessage);
              TEXT_PrintGameString(wszFormatBuf, pMessage->messageColor);
              return;
            }

            break;
          }
        case 5:
          {
            if (unit) {
              TEXT_SetUnitHoverText((uint32_t)pMessage->language, pszName, pMessage->language, unit);
              return;
            }

            break;
          }
        case 7:
          {
            Fog::File::CONTAINER_InitializeBuffer(wcWideStart, 2, 0x100, D2Lang::Unicode::UNISYS::STRING_ZeroOneWCHAR);
            /* int cchWideChar for MultiByteToWideChar */ /* LPWSTR lpWideCharStr for MultiByteToWideChar */ /* int cbMultiByte for MultiByteToWideChar */ /* LPCSTR lpMultiByteStr for MultiByteToWideChar */ /* DWORD dwFlags for MultiByteToWideChar */ /* UINT CodePage for MultiByteToWideChar */ MultiByteToWideChar(0, 1, pszName, 0x100, (LPWSTR)wcWideStart, 0x100);
            byMsgType = pMessage->language;
            nCheckResult = D2Lang::StrTable::strtable::MISC_GetLanguageCode();
            if (byMsgType != nCheckResult) {
              pszWideOut = wcWideStart;
              while (wcWideStart[0] != L'\0') {
                pszWideOut++;
                wcWideStart[0] = *pszWideOut;
              }
            }

            Inv::CloseScrollOfWhatever(wcWideStart, (uint32_t)pMessage->messageColor);
            break;
          }
      }
    }
}

void __fastcall TEXT_ClearUnitHoverText(D2GSPacketSrv0x76 * pPacket) {
    D2UnitStrc* pUnit = UNIT::Player::UNITS_FindClientSideUnit(pPacket->nUnitGUID, (eD2UnitType)pPacket->nUnitType);
    if (!pUnit) {
      return;
    }
    if (pUnit->pHoverText) {
      D2Common::Chat::Free(nullptr, pUnit->pHoverText);
    }

    pUnit->pHoverText = 0;
}

