void __stdcall INPUT_TextDismiss(D2UIMouseMsgStrc * pMsg) {
    gbTextScrollBoxVisible = 0;
    DWORD dwTickCount = GetTickCount();
    if (dwTickCount - gbTextNpcMenuActive < 100) {
      pMsg->bHandled = 1;
      pMsg->dwResult = 0;
      Storm::SMsgBreakHandlerChain(pMsg);
      gpTextDismissCallback = 0;
      return;
    }

    int bHandled = TEXT_HandleEscapeKey();
    if (!bHandled) {
      return;
    }

    pMsg->bHandled = 1;
    pMsg->dwResult = 0;
    Storm::SMsgBreakHandlerChain(pMsg);
}

void __stdcall INPUT_TextClickHandler(D2UIMouseMsgStrc * pMsg) {
    D2UnitStrc* pNpcUnit;
    gpTextDismissCallback = 1;
    D2UnitStrc* pSelectedUnit = GAME::Select::GetSelectedUnit();
    if (pSelectedUnit) {
      if (gnTextNpcInteractGuid) {
        pSelectedUnit = UNIT::Player::UNITS_FindClientSideUnit(gnTextNpcGuid, UNIT_MONSTER);
        pNpcUnit = GAME::Select::GetSelectedUnit();
        if (pSelectedUnit == pNpcUnit) {
          return;
        }
      }
    } else {
      pSelectedUnit = GAME::Select::GetSelectedUnit();
      if (!pSelectedUnit && gbTextNpcMenuSelection != '\0') {
        pSelectedUnit = UNIT::Player::UNITS_FindClientSideUnit(gnTextNpcMenuIndex, UNIT_MONSTER);
        if (!pSelectedUnit) {
          return;
        }

        pNpcUnit = UNIT::Player::UNITS_FindClientSideUnit(gnTextNpcGuid, UNIT_MONSTER);
        if (pSelectedUnit != pNpcUnit) {
          return;
        }

        pMsg->bHandled = 1;
        pMsg->dwResult = 0;
        Storm::SMsgBreakHandlerChain(pMsg);
        return;
      }
    }

    INPUT_TextDismiss(pMsg);
}

void __stdcall INPUT_TextKeyHandler(D2UIMouseMsgStrc * pMsg) {
    uint32_t bIsBound = CmdTbl::CMD_IsCommandBound(7, 1);
    if (bIsBound) {
      uint16_t wBoundKey;
      wBoundKey = CmdTbl::CMD_GetKeyForCommand(7, 1);
      if (wBoundKey != 0xffff && wBoundKey <= 0xdf && pMsg->nWParam == (uint32_t)wBoundKey) {
        return;
      }
    }

    INPUT_TextDismiss(pMsg);
}

void __stdcall INPUT_TextKeyFilter(D2UIMouseMsgStrc * pMsg) {
    if (pMsg->nWParam == 0x73) {
      return;
    }

    INPUT_TextKeyHandler(pMsg);
}

